const assert=require('node:assert/strict');
const fs=require('node:fs');
const path=require('node:path');
const vm=require('node:vm');
const text=fs.readFileSync(path.join(__dirname,'../../index.html'),'utf8');
const begin=text.indexOf('function evfFlatten(s){');
const end=text.indexOf('async function evolveFitCloudSave',begin);
assert.ok(begin>0&&end>begin);
const context={clone:obj=>JSON.parse(JSON.stringify(obj)),Date};
vm.createContext(context);
vm.runInContext(text.slice(begin,end),context);
const {evfFlatten,evfFlatEqual,evfMerge3}=context;
assert.equal(evfFlatEqual({'a':1,'b':2},{'b':2,'a':1}),true,'ordem dos campos não implica divergência');
assert.equal(evfFlatEqual({'a':1,'b':2},{'a':1,'b':3}),false);
assert.equal(evfFlatEqual({'a':undefined},{'b':undefined}),false,'chaves diferentes não são equivalentes');
const base={_updatedAt:1,days:{'2026-11-05':{water:0,tasks:{}}},body:[],sessions:[],trainingCompleted:{},profile:{name:'User',proteinTarget:170},plano:[]};
const local=JSON.parse(JSON.stringify(base));local._updatedAt=2;local.body.push({date:'2026-11-05',weight:93});local.sessions.push({id:'s1',date:'2026-11-05',ex:[{exerciseChecked:true,rir:null}]});
const remote=JSON.parse(JSON.stringify(base));remote._updatedAt=3;remote.days['2026-11-05'].tasks.passos={value:10000,done:true};remote.profile.proteinTarget=185;
const merged=evfMerge3(evfFlatten(base),local,remote);
assert.equal(merged.body[0].weight,93,'Corpo local mantém pesagem');
assert.equal(merged.sessions[0].ex[0].exerciseChecked,true,'Treinos local mantém check');
assert.equal(merged.days['2026-11-05'].tasks.passos.value,10000,'Hoje remoto mantém passos');
assert.equal(merged.profile.proteinTarget,185,'Coach remoto mantém meta');
const deleted=JSON.parse(JSON.stringify(base));deleted._updatedAt=4;deleted.days={};
const fromOther=JSON.parse(JSON.stringify(base));fromOther._updatedAt=5;fromOther.body=[{date:'2026-11-06',weight:92}];
const result=evfMerge3(evfFlatten(base),deleted,fromOther);
assert.equal(result.days['2026-11-05'],undefined,'eliminação explícita propaga-se');
assert.equal(result.body[0].weight,92,'medição independente não desaparece');
console.log('Fusão local/nuvem: igualdade estável, dados de menus diferentes unidos e eliminações preservadas.');
